import json
from datetime import datetime
from pathlib import Path

import pandas as pd

OUT = Path('/app')

# Read each source independently, retaining the source-specific priority.
sources = {
    'source_a': json.loads(Path('/data/source_a/users.json').read_text()),
    'source_b': pd.read_csv('/data/source_b/users.csv').to_dict('records'),
    'source_c': pd.read_parquet('/data/source_c/users.parquet').to_dict('records'),
}

field_aliases = {
    'user_id': ('user_id', 'id', 'userId'),
    'name': ('name', 'full_name', 'userName'),
    'email': ('email', 'email_address'),
    'created_date': ('registration_date', 'created_at', 'joined'),
}


def value_for(row, aliases):
    for key in aliases:
        if key in row and pd.notna(row[key]):
            return row[key]
    return None


def normalize_date(value):
    if value is None:
        return None
    # Parse dates rather than merely slicing, then emit the required format.
    return pd.to_datetime(value).strftime('%Y-%m-%d')


def normalize_status(row):
    if 'status' in row and pd.notna(row['status']):
        return str(row['status']).lower()
    for key in ('is_active', 'active'):
        if key in row and pd.notna(row[key]):
            value = row[key]
            if isinstance(value, str):
                value = value.strip().lower() in ('true', '1', 'yes', 'active')
            return 'active' if bool(value) else 'inactive'
    return None

normalized = {}
for source, rows in sources.items():
    normalized[source] = {}
    for row in rows:
        user_id = value_for(row, field_aliases['user_id'])
        if user_id is None:
            raise ValueError(f'{source} contains a record without a user id')
        user_id = int(user_id)
        record = {
            'user_id': user_id,
            'name': value_for(row, field_aliases['name']),
            'email': value_for(row, field_aliases['email']),
            'created_date': normalize_date(value_for(row, field_aliases['created_date'])),
            'status': normalize_status(row),
        }
        normalized[source][user_id] = record

priority = ('source_a', 'source_b', 'source_c')
all_ids = sorted({uid for source in normalized.values() for uid in source})
fields = ('name', 'email', 'created_date', 'status')
merged = []
conflicts = []

for user_id in all_ids:
    records = {source: normalized[source][user_id] for source in priority if user_id in normalized[source]}
    selected = next(records[source] for source in priority if source in records)
    output = {'user_id': user_id}
    for field in fields:
        # Highest-priority non-null value wins (a missing value does not erase
        # a value supplied by a lower-priority source).
        output[field] = next((records[source][field] for source in priority
                              if source in records and records[source][field] is not None), None)
        present = {source: records[source][field] for source in priority
                   if source in records and records[source][field] is not None}
        if len(set(present.values())) > 1:
            conflicts.append({
                'user_id': user_id,
                'field': field,
                'values': present,
                'selected': output[field],
            })
    merged.append(output)

# Keep the optional status column only when at least one source supplied it.
columns = ['user_id', 'name', 'email', 'created_date']
if any(row['status'] is not None for row in merged):
    columns.append('status')
result = pd.DataFrame(merged, columns=columns)
result['user_id'] = result['user_id'].astype('int64')
for column in ('name', 'email', 'created_date'):
    result[column] = result[column].astype('string')
if 'status' in result:
    result['status'] = result['status'].astype('string')
result.to_parquet(OUT / 'merged_users.parquet', index=False, engine='pyarrow')

(OUT / 'conflicts.json').write_text(json.dumps({
    'total_conflicts': len(conflicts),
    'conflicts': conflicts,
}, indent=2) + '\n')
PY
python /app/merge_users.py
